import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Days NYC 2023: Ceph Crossing the Chasm","description":"","frontmatter":{"title":"Ceph Days NYC 2023: Ceph Crossing the Chasm","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-17T00:00:00.000Z","tags":["Ceph","分布式存储","IBM","开源","存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Crossing_the_Chasm.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Crossing_the_Chasm.md","lastUpdated":1780459816000}'),p={name:"posts/2023/Ceph_Days_NYC_2023_-_Ceph_Crossing_the_Chasm.md"};function o(n,l,r,_,h,a){return s(),t("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph存储技术的未来与IBM的战略整合</p><p><strong>主讲人：</strong> Vincent Shu，IBM Fellow兼存储部门CTO</p><p><strong>会议时间：</strong> 2023年1月1日</p><p><strong>会议地点：</strong> Ceph Days NYC 2023</p><p><strong>参会人员：</strong> Ceph社区成员及IBM代表</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>个人介绍与背景：</strong></p><ul><li>Vincent Shu拥有30年存储行业经验，加入IBM后成为Ceph社区的新成员。</li><li>对存储技术充满热情，并对Ceph技术表示支持。</li></ul></li><li><p><strong>IBM与Ceph的整合：</strong></p><ul><li>IBM于2023年1月1日正式将Ceph团队纳入其存储部门。</li><li>IBM承诺将继续坚持开源优先的战略，保证Ceph的100%开源和上游开发。</li><li>IBM成为Ceph基金会的premium member，加强社区合作。</li></ul></li><li><p><strong>存储行业的历史与现状：</strong></p><ul><li>从专用硬件到软件定义存储，存储行业经历了多次变革。</li><li>当前数据中心存在多种存储技术，导致管理复杂，创新速度慢。</li></ul></li><li><p><strong>未来的存储愿景：</strong></p><ul><li>目标是实现一个可编程、统一、API驱动的软件定义存储平台，支持混合云环境。</li><li>强调存储的智能化，包括自我监控、自我调整和基于遥测技术的自主管理。</li></ul></li><li><p><strong>IBM在Ceph社区的贡献与未来计划：</strong></p><ul><li>聚焦于可消费性、自动化、云和数据管理、以及网络安全。</li><li>计划通过AI Ops等技术加速价值实现时间，简化管理，提高数据管理的灵活性和安全性。</li></ul></li><li><p><strong>具体技术与项目：</strong></p><ul><li>讨论了数据复制、自动化灾难恢复解决方案、加密支持等具体技术。</li><li>强调了这些技术如何帮助客户更快地恢复数据，减少网络攻击的影响。</li></ul></li><li><p><strong>开放性问题与后续行动：</strong></p><ul><li>Vincent Shu鼓励社区成员提出问题和建议，共同推动Ceph和存储技术的发展。</li><li>他承诺将跟进社区的反馈，并继续推动IBM在Ceph社区的领导和贡献。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>加强IBM与Ceph社区的合作，确保技术路线图与市场需求一致。</li><li>推动更多自动化和智能化功能，提高存储管理的效率和安全性。</li><li>加强与客户的沟通，确保产品和服务满足他们的实际需求。</li></ul><p><strong>备注：</strong></p><ul><li>Vincent Shu强调了他作为Ceph新成员的角色，并承诺将积极参与社区活动。</li><li>他鼓励与会者不要担心IBM对Ceph的整合会改变其开源性质，IBM将继续支持Ceph的发展。</li></ul>',12)])])}const u=e(p,[["render",o]]);export{g as __pageData,u as default};
